from __future__ import annotations

from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if text.count(old) != 1:
        raise SystemExit(f"{label}: expected exactly one match, got {text.count(old)}")
    return text.replace(old, new, 1)


# 1. Add multiscale online-learning weights.
adaptive_path = ROOT / "server/app/adaptive_learning.py"
adaptive = adaptive_path.read_text(encoding="utf-8")
if "def multiscale_strategy_weights(" not in adaptive:
    adaptive += '''\n\nMULTISCALE_WINDOWS = ((100, 0.50), (300, 0.30), (None, 0.20))\n\n\ndef multiscale_strategy_weights(\n    events: Iterable[Mapping[str, object]],\n    fallback: Mapping[str, float] | None = None,\n) -> dict[str, float]:\n    \"\"\"Build stable online weights from recent 100, recent 300 and all history.\n\n    Each window is reliability-shrunk until enough settled forecasts exist, so a\n    new installation with only a few dozen samples cannot violently overfit.\n    \"\"\"\n    grouped: dict[str, list[dict[str, object]]] = {}\n    for raw in events:\n        strategy = str(raw.get(\"strategy\") or \"\").strip()\n        if not strategy:\n            continue\n        try:\n            log_loss = float(raw.get(\"log_loss\"))\n            brier = float(raw.get(\"brier_score\"))\n        except (TypeError, ValueError):\n            continue\n        if not math.isfinite(log_loss) or not math.isfinite(brier):\n            continue\n        grouped.setdefault(strategy, []).append(\n            {\n                \"log_loss\": log_loss,\n                \"brier_score\": brier,\n                \"top6_hit\": bool(raw.get(\"top6_hit\")),\n                \"settled_at\": int(raw.get(\"settled_at\") or 0),\n            }\n        )\n\n    names = tuple(dict.fromkeys([*(fallback or {}).keys(), *grouped.keys()]))\n    if not names:\n        return {}\n    prior = normalize_strategy_weights(fallback, names)\n    if not grouped:\n        return prior\n\n    scores: dict[str, float] = {}\n    for strategy in names:\n        rows = sorted(\n            grouped.get(strategy, []),\n            key=lambda item: int(item[\"settled_at\"]),\n            reverse=True,\n        )\n        evidence_log_score = 0.0\n        for limit, mix in MULTISCALE_WINDOWS:\n            subset = rows if limit is None else rows[:limit]\n            if not subset:\n                continue\n            combined_losses = [\n                0.8 * float(item[\"log_loss\"])\n                + 0.2 * (float(item[\"brier_score\"]) / 0.9) * UNIFORM_LOG_LOSS\n                for item in subset\n            ]\n            mean_loss = sum(combined_losses) / len(combined_losses)\n            hit_rate = sum(bool(item[\"top6_hit\"]) for item in subset) / len(subset)\n            loss_advantage = max(-1.5, min(1.5, UNIFORM_LOG_LOSS - mean_loss))\n            hit_advantage = max(-0.6, min(0.6, (hit_rate - 0.60) * 1.5))\n            target = 500 if limit is None else limit\n            reliability = min(1.0, len(subset) / float(target))\n            evidence_log_score += mix * reliability * (loss_advantage + 0.25 * hit_advantage)\n        scores[strategy] = max(1e-12, prior[strategy]) * math.exp(evidence_log_score)\n    return _bounded_normalize(scores)\n'''
adaptive_path.write_text(adaptive, encoding="utf-8")

# 2. Make DB prediction weights use settled 100/300/all windows.
db_path = ROOT / "server/app/db.py"
db = db_path.read_text(encoding="utf-8")
db = replace_once(
    db,
    "from .adaptive_learning import prediction_loss, update_strategy_weights",
    "from .adaptive_learning import (\n    multiscale_strategy_weights,\n    prediction_loss,\n    update_strategy_weights,\n)",
    "db adaptive import",
)
old_get = '''    def get_strategy_weights(self, lottery: str, source: str) -> dict[str, float]:\n        with self.connection() as db:\n            rows = db.execute(\n                \"\"\"\n                SELECT strategy, weight\n                FROM strategy_learning\n                WHERE lottery = ? AND source = ?\n                \"\"\",\n                (lottery, source),\n            ).fetchall()\n        return {str(row[\"strategy\"]): float(row[\"weight\"]) for row in rows}\n'''
new_get = '''    def get_strategy_weights(self, lottery: str, source: str) -> dict[str, float]:\n        with self.connection() as db:\n            stored_rows = db.execute(\n                \"\"\"\n                SELECT strategy, weight\n                FROM strategy_learning\n                WHERE lottery = ? AND source = ?\n                \"\"\",\n                (lottery, source),\n            ).fetchall()\n            event_rows = db.execute(\n                \"\"\"\n                SELECT strategy, log_loss, brier_score, top6_hit, settled_at\n                FROM forecast_strategy_predictions\n                WHERE lottery = ? AND source = ? AND settled_at IS NOT NULL\n                ORDER BY settled_at DESC, forecast_id DESC\n                \"\"\",\n                (lottery, source),\n            ).fetchall()\n        stored = {str(row[\"strategy\"]): float(row[\"weight\"]) for row in stored_rows}\n        if not event_rows:\n            return stored\n        # Use neutral/default priors once real events exist. The old sequential\n        # weight is intentionally not used as a second historical vote.\n        return multiscale_strategy_weights([dict(row) for row in event_rows])\n'''
db = replace_once(db, old_get, new_get, "get_strategy_weights")
old_summary = '''    def strategy_learning_summary(self, lottery: str, source: str) -> list[dict[str, object]]:\n        with self.connection() as db:\n            rows = db.execute(\n                \"\"\"\n                SELECT strategy, weight, samples, ema_log_loss, ema_brier,\n                       top6_hits, top6_misses, updated_at\n                FROM strategy_learning\n                WHERE lottery = ? AND source = ?\n                ORDER BY weight DESC, strategy ASC\n                \"\"\",\n                (lottery, source),\n            ).fetchall()\n        return [dict(row) for row in rows]\n'''
new_summary = '''    def strategy_learning_summary(self, lottery: str, source: str) -> list[dict[str, object]]:\n        effective = self.get_strategy_weights(lottery, source)\n        with self.connection() as db:\n            rows = db.execute(\n                \"\"\"\n                SELECT strategy, weight, samples, ema_log_loss, ema_brier,\n                       top6_hits, top6_misses, updated_at\n                FROM strategy_learning\n                WHERE lottery = ? AND source = ?\n                \"\"\",\n                (lottery, source),\n            ).fetchall()\n        result: list[dict[str, object]] = []\n        for row in rows:\n            item = dict(row)\n            strategy = str(item[\"strategy\"])\n            samples = int(item.get(\"samples\") or 0)\n            item[\"stored_weight\"] = float(item[\"weight\"])\n            item[\"weight\"] = float(effective.get(strategy, item[\"weight\"]))\n            item[\"recent_100_samples\"] = min(100, samples)\n            item[\"recent_300_samples\"] = min(300, samples)\n            item[\"all_samples\"] = samples\n            item[\"weight_mode\"] = \"recent100_50_recent300_30_all_20\"\n            result.append(item)\n        result.sort(key=lambda item: (-float(item[\"weight\"]), str(item[\"strategy\"])))\n        return result\n'''
db = replace_once(db, old_summary, new_summary, "strategy_learning_summary")
db = db.replace(
    'if model == "tianji-native-cloud-v4":',
    'if model.startswith("tianji-native-cloud-v"):',
)
db_path.write_text(db, encoding="utf-8")

# 3. Preserve reviewer order and make AI genuinely independent from native math.
ai_path = ROOT / "server/app/ai_ensemble.py"
ai = ai_path.read_text(encoding="utf-8")
run_pattern = re.compile(r"def _run_prefix_cached\(count: int, task: Any\) -> list\[_ReviewerResult\]:\n.*?(?=\n\ndef _aggregate)", re.S)
run_replacement = '''def _run_prefix_cached(count: int, task: Any) -> list[_ReviewerResult]:\n    \"\"\"Complete one real review first, then run the rest while preserving IDs.\"\"\"\n    indexed: dict[int, _ReviewerResult] = {}\n    errors: list[str] = []\n    warm_count = min(1, max(0, count))\n    for reviewer in range(warm_count):\n        try:\n            indexed[reviewer] = task(reviewer)\n        except Exception as exc:  # noqa: BLE001\n            errors.append(str(exc)[:180])\n    remaining = list(range(warm_count, count))\n    if remaining:\n        with ThreadPoolExecutor(\n            max_workers=len(remaining),\n            thread_name_prefix=\"tianji-ai-cache-hit\",\n        ) as pool:\n            futures = {pool.submit(task, reviewer): reviewer for reviewer in remaining}\n            for future in as_completed(futures):\n                reviewer = futures[future]\n                try:\n                    indexed[reviewer] = future.result()\n                except Exception as exc:  # noqa: BLE001\n                    errors.append(str(exc)[:180])\n    if not indexed:\n        raise RuntimeError(\"全部AI评审失败：\" + \"；\".join(errors[:3]))\n    return [indexed[index] for index in sorted(indexed)]\n'''
ai, count = run_pattern.subn(run_replacement, ai)
if count != 1:
    raise SystemExit(f"_run_prefix_cached replacement count={count}")

analyze_pattern = re.compile(r"def analyze_ensemble\(\n.*\Z", re.S)
analyze_replacement = '''def analyze_ensemble(\n    history: list[DrawModel],\n    target_period: str,\n    config: RuntimeAiConfig,\n    *,\n    recent_positions: list[int] | None = None,\n    strategy_weights: dict[str, float] | None = None,\n) -> AiEnsembleResult:\n    if not config.complete:\n        raise RuntimeError(\"服务器尚未完整配置AI\")\n    verified = _canonical_history(history)\n    if len(verified) < 30:\n        raise ValueError(\"AI预测至少需要30期有效历史\")\n    trained_through = verified[-1].period\n    started = time.monotonic()\n    evidence = build_position_evidence(verified)\n\n    # AI source is intentionally independent: no native statistical component\n    # participates in position selection or number ranking.\n    position_results = _run_prefix_cached(\n        _POSITION_REVIEWERS,\n        lambda reviewer: _position_review(\n            config,\n            history=verified,\n            evidence=evidence,\n            target_period=target_period,\n            trained_through_period=trained_through,\n            reviewer=reviewer,\n            challenge=False,\n        ),\n    )\n    position_scores = _aggregate(position_results)\n    selected_position = max(range(10), key=position_scores.__getitem__)\n    recent = recent_positions or []\n    collapse_reviewed = needs_collapse_review(recent, selected_position)\n    if collapse_reviewed:\n        challenge_results = _run_prefix_cached(\n            2,\n            lambda reviewer: _position_review(\n                config,\n                history=verified,\n                evidence=evidence,\n                target_period=target_period,\n                trained_through_period=trained_through,\n                reviewer=reviewer + 100,\n                challenge=True,\n            ),\n        )\n        position_results.extend(challenge_results)\n        position_scores = _aggregate(position_results)\n        selected_position = max(range(10), key=position_scores.__getitem__)\n\n    number_results = _run_prefix_cached(\n        _NUMBER_REVIEWERS,\n        lambda reviewer: _number_review(\n            config,\n            history=verified,\n            position=selected_position,\n            target_period=target_period,\n            trained_through_period=trained_through,\n            reviewer=reviewer,\n            mask_recent=0,\n        ),\n    )\n    strategy_probabilities = {\n        f\"ai_reviewer_{index + 1}\": _normalize(result.scores)\n        for index, result in enumerate(number_results)\n    }\n    active_strategy_weights = normalize_strategy_weights(\n        strategy_weights,\n        strategy_probabilities,\n    )\n    probabilities = blend_strategy_probabilities(\n        strategy_probabilities,\n        active_strategy_weights,\n    )\n    ranked = sorted(range(10), key=probabilities.__getitem__, reverse=True)\n\n    raw_copy = recent_copy_diagnostics(ranked, verified, selected_position)\n    ai_score_spread = max(probabilities) - min(probabilities)\n    final_boundary = probabilities[ranked[5]] - probabilities[ranked[6]]\n    recent_copy_reviewed = (\n        raw_copy.exact_latest_six\n        or (raw_copy.triggered and ai_score_spread >= 0.02 and final_boundary >= 0.004)\n    )\n    holdout_results: list[_ReviewerResult] = []\n    if recent_copy_reviewed:\n        holdout_results = _run_prefix_cached(\n            _NUMBER_REVIEWERS,\n            lambda reviewer: _number_review(\n                config,\n                history=verified,\n                position=selected_position,\n                target_period=target_period,\n                trained_through_period=trained_through,\n                reviewer=reviewer + 100,\n                mask_recent=_RECENT_COPY_WINDOW,\n            ),\n        )\n        number_results.extend(holdout_results)\n        for index, result in enumerate(holdout_results):\n            strategy_probabilities[f\"ai_holdout_{index + 1}\"] = _normalize(result.scores)\n        learned = dict(strategy_weights or {})\n        if not any(name.startswith(\"ai_holdout_\") for name in learned):\n            for name in strategy_probabilities:\n                learned.setdefault(name, 0.35 if name.startswith(\"ai_holdout_\") else 0.15)\n        active_strategy_weights = normalize_strategy_weights(\n            learned,\n            strategy_probabilities,\n        )\n        probabilities = blend_strategy_probabilities(\n            strategy_probabilities,\n            active_strategy_weights,\n        )\n        ranked = sorted(range(10), key=probabilities.__getitem__, reverse=True)\n\n    position_margin = sorted(position_scores, reverse=True)\n    margin = (\n        (position_margin[0] - position_margin[1]) * 100\n        if len(position_margin) > 1\n        else 0.0\n    )\n    position_comment = next((item.analysis for item in position_results if item.analysis), \"\")\n    number_comment_source = holdout_results or number_results\n    number_comment = next((item.analysis for item in number_comment_source if item.analysis), \"\")\n    analysis = (\n        f\"{len(position_results)}轮独立AI匿名名次评审选择第{selected_position + 1}名，\"\n        f\"前两名次AI评分差约{margin:.2f}个百分点；\"\n        f\"{len(number_results)}轮独立AI匿名时序评审完成号码排序。\"\n        + (f\" {position_comment}\" if position_comment else \"\")\n        + (f\" {number_comment}\" if number_comment else \"\")\n        + \" AI预测不再混入本地频率、遗漏、马尔可夫、趋势或稳定性策略。\"\n    )[:520]\n    if collapse_reviewed:\n        analysis = (analysis + \" 已触发连续同名次的额外AI挑战评审。\")[:580]\n    if recent_copy_reviewed:\n        analysis = (\n            analysis + \" 初次结果与最近集合高度重合，已增加隐藏最近7期的独立AI留出评审。\"\n        )[:640]\n    learning_leaders = sorted(\n        active_strategy_weights.items(),\n        key=lambda item: item[1],\n        reverse=True,\n    )[:3]\n    learning_text = \"、\".join(\n        f\"{name} {weight * 100:.1f}%\" for name, weight in learning_leaders\n    )\n    analysis = (\n        analysis\n        + f\" AI评审权重按最近100期50%、最近300期30%、全历史20%独立学习：{learning_text}。\"\n    )[:760]\n\n    usage = _merge_usage([*position_results, *number_results])\n    cache_input_tokens = usage[\"prompt_cache_hit_tokens\"] + usage[\"prompt_cache_miss_tokens\"]\n    cache_hit_rate = (\n        usage[\"prompt_cache_hit_tokens\"] / cache_input_tokens\n        if cache_input_tokens\n        else 0.0\n    )\n\n    return AiEnsembleResult(\n        position=selected_position,\n        probabilities=probabilities,\n        top6=[index + 1 for index in ranked[:6]],\n        top7=[index + 1 for index in ranked[:7]],\n        analysis=analysis,\n        risk_note=(\n            \"这是开奖前冻结的独立AI多路匿名排序。AI只读取匿名历史与证据，不再复用本地模型最终概率；\"\n            \"本地数学模型与AI模型分别结算、分别学习。随机开奖仍可能使任何分析失效。\"\n        ),\n        latency_ms=int((time.monotonic() - started) * 1000),\n        position_reviewers=len(position_results),\n        number_reviewers=len(number_results),\n        collapse_reviewed=collapse_reviewed,\n        recent_copy_reviewed=recent_copy_reviewed,\n        request_count=usage[\"request_count\"],\n        prompt_tokens=usage[\"prompt_tokens\"],\n        prompt_cache_hit_tokens=usage[\"prompt_cache_hit_tokens\"],\n        prompt_cache_miss_tokens=usage[\"prompt_cache_miss_tokens\"],\n        completion_tokens=usage[\"completion_tokens\"],\n        reasoning_tokens=usage[\"reasoning_tokens\"],\n        cache_hit_rate=round(cache_hit_rate, 6),\n        strategy_probabilities=strategy_probabilities,\n        strategy_weights=active_strategy_weights,\n    )\n'''
ai, count = analyze_pattern.subn(analyze_replacement, ai)
if count != 1:
    raise SystemExit(f"analyze_ensemble replacement count={count}")
ai_path.write_text(ai, encoding="utf-8")

# 4. Version and forced runtime rebuild.
service_path = ROOT / "server/app/service.py"
service = service_path.read_text(encoding="utf-8")
service = replace_once(service, 'SERVICE_VERSION = "1.7.4"', 'SERVICE_VERSION = "1.8.0"', "service version")
service_path.write_text(service, encoding="utf-8")
compose_path = ROOT / "docker-compose.yml"
compose = compose_path.read_text(encoding="utf-8")
compose = compose.replace('1.7.4-learning-settlement', '1.8.0-multiscale-independent-ai')
compose_path.write_text(compose, encoding="utf-8")

# 5. Update and extend regression tests.
adaptive_test_path = ROOT / "server/tests/test_adaptive_learning.py"
adaptive_test = adaptive_test_path.read_text(encoding="utf-8")
adaptive_test = replace_once(
    adaptive_test,
    "    blend_strategy_probabilities,\n    prediction_loss,",
    "    blend_strategy_probabilities,\n    multiscale_strategy_weights,\n    prediction_loss,",
    "adaptive test import",
)
anchor = "\n    def test_blend_follows_updated_weights(self) -> None:\n"
new_test = '''\n    def test_multiscale_weights_favor_recent_recovery_without_35_sample_overfit(self) -> None:\n        events: list[dict[str, object]] = []\n        now = 10_000\n        for index in range(400):\n            recent = index < 100\n            for strategy in (\"recent_winner\", \"old_winner\"):\n                winner = (strategy == \"recent_winner\") if recent else (strategy == \"old_winner\")\n                events.append(\n                    {\n                        \"strategy\": strategy,\n                        \"log_loss\": 1.45 if winner else 3.15,\n                        \"brier_score\": 0.62 if winner else 1.08,\n                        \"top6_hit\": winner,\n                        \"settled_at\": now - index,\n                    }\n                )\n        weights = multiscale_strategy_weights(events)\n        self.assertGreater(weights[\"recent_winner\"], weights[\"old_winner\"])\n        self.assertAlmostEqual(sum(weights.values()), 1.0, places=8)\n\n        young = [item for item in events if int(item[\"settled_at\"]) > now - 35]\n        young_weights = multiscale_strategy_weights(young)\n        self.assertLess(max(young_weights.values()), 0.65)\n'''
if anchor not in adaptive_test:
    raise SystemExit("adaptive test anchor missing")
adaptive_test = adaptive_test.replace(anchor, new_test + anchor, 1)
adaptive_test_path.write_text(adaptive_test, encoding="utf-8")

ai_test_path = ROOT / "server/tests/test_ai_ensemble.py"
ai_test = ai_test_path.read_text(encoding="utf-8")
ai_test = ai_test.replace(
    "def test_final_prediction_blends_ai_with_forward_validation(",
    "def test_final_prediction_is_independent_from_native_math(",
)
old_asserts = '''        self.assertEqual(result.position, 3)\n        self.assertEqual(result.top6[0], 8)\n        self.assertTrue(result.collapse_reviewed)\n        self.assertIn(\"AI多轮\", result.risk_note)\n        self.assertIn(\"不再机械锁死\", result.analysis)\n'''
new_asserts = '''        self.assertEqual(result.position, 3)\n        self.assertEqual(result.top6[0], 8)\n        self.assertTrue(result.collapse_reviewed)\n        self.assertTrue(result.strategy_probabilities)\n        self.assertTrue(all(name.startswith(\"ai_\") for name in result.strategy_probabilities))\n        self.assertFalse(\n            {\"long_frequency\", \"recent_frequency\", \"markov_transition\"}\n            & set(result.strategy_probabilities)\n        )\n        self.assertIn(\"独立AI\", result.risk_note)\n        self.assertIn(\"不再混入本地\", result.analysis)\n'''
ai_test = replace_once(ai_test, old_asserts, new_asserts, "AI independent assertions")
ai_test_path.write_text(ai_test, encoding="utf-8")

version_test_path = ROOT / "server/tests/test_adaptive_worker_runtime.py"
version_test = version_test_path.read_text(encoding="utf-8")
version_test = version_test.replace('self.assertEqual(SERVICE_VERSION, "1.7.4")', 'self.assertEqual(SERVICE_VERSION, "1.8.0")')
